import { z } from "zod";

import type { RiskClass } from "./release.ts";

/**
 * Immutable release artifact (docs/MIGRATION-PLAN.md §2.1, ADR D-146).
 *
 * A release is a tag plus this artifact: the DDL for `from` -> `to`, generated by the
 * release pipeline from the two declared schema snapshots (no database involved), stored
 * as a CI artifact keyed by the release tag and never committed. The deploy applies it
 * verbatim after checking the live digest and, for destructive batches, an approval bound
 * to `planHash`.
 *
 * Everything in this module is a code contract: `parseReleaseArtifact` reports machine
 * issues (`path` + zod `code`), never prose, matching the API convention in ./errors.ts.
 */

export const RELEASE_ARTIFACT_FORMAT_VERSION = 1;

/** Digest projection this contract was written against; see @facilis/db SCHEMA_DIGEST_VERSION. */
const DIGEST_VERSION = 1;

const RISK_CLASSES = ["safe", "careful", "destructive", "breaking"] as const;

/** `v<digestVersion>:sha256:<64 lowercase hex>`, the only digest spelling v1 accepts. */
const DIGEST = /^v1:sha256:[0-9a-f]{64}$/;
/** `sha256:<64 lowercase hex>`: the plan hash has no version prefix (formatVersion covers it). */
const PLAN_HASH = /^sha256:[0-9a-f]{64}$/;

export interface ReleaseRef {
  /** Tag name, e.g. `v1.4.0`; for the previous release it is the resolved previous tag. */
  readonly tag: string;
  /** Git commit the tag pointed at, so the plan names exactly the trees it read. */
  readonly oid: string;
}

export interface ReleaseBatch {
  /** Stable id, unique inside the artifact; `destructive` and `requires` name batches by it. */
  readonly id: string;
  /** v1 ships DDL only; hand-written data batches are out of scope (decision 5). */
  readonly kind: "ddl";
  /** The statement(s) of this batch, rendered by the generator. */
  readonly sql: string;
  readonly risk: RiskClass;
  /** Preconditions the deploy checks before running the batch, e.g. row-count requirements. */
  readonly requires?: readonly string[];
}

export interface ReleaseProblem {
  /** Machine code, e.g. `unsupported_declaration` or `data_needed`; P2 owns the vocabulary. */
  readonly code: string;
  /** Batch the problem is attached to, when it has one. */
  readonly batch?: string;
}

export interface ReleaseApproval {
  /** Who approved the destructive part of the plan. */
  readonly by: string;
  /** ISO-8601 timestamp of the approval act (the contract does not re-format it). */
  readonly at: string;
  /** Must equal `planHash`: the approval names the exact SQL it approves. */
  readonly hash: string;
}

export interface ReleaseArtifact {
  readonly formatVersion: typeof RELEASE_ARTIFACT_FORMAT_VERSION;
  /** The release tag this artifact belongs to and is stored under; normally equals `to.tag`. */
  readonly tag: string;
  readonly from: ReleaseRef;
  readonly to: ReleaseRef;
  readonly digestVersion: typeof DIGEST_VERSION;
  readonly fromDigest: string;
  readonly toDigest: string;
  readonly planHash: string;
  readonly risk: RiskClass;
  /** Ids of the batches that drop or lose data: the list an approval is bound to. */
  readonly destructive: readonly string[];
  /** Ordered: the deploy runs them in this order, one transaction per artifact. */
  readonly batches: readonly ReleaseBatch[];
  /** Non-empty means the release must fail; the deploy never receives such an artifact. */
  readonly problems: readonly ReleaseProblem[];
  readonly approved?: ReleaseApproval;
  readonly generatedBy: string;
  readonly generatedAt: string;
}

/**
 * Schema of the public contract. Cross-field checks (e.g. `destructive` naming existing
 * batches) belong to the generator and the deploy: this schema validates the artifact as
 * it travels between them.
 */
export const releaseArtifactSchema: z.ZodType<ReleaseArtifact> = z.strictObject({
  formatVersion: z.literal(RELEASE_ARTIFACT_FORMAT_VERSION),
  tag: z.string().min(1),
  from: z.strictObject({ tag: z.string().min(1), oid: z.string().min(1) }),
  to: z.strictObject({ tag: z.string().min(1), oid: z.string().min(1) }),
  digestVersion: z.literal(DIGEST_VERSION),
  fromDigest: z.string().regex(DIGEST),
  toDigest: z.string().regex(DIGEST),
  planHash: z.string().regex(PLAN_HASH),
  risk: z.enum(RISK_CLASSES),
  destructive: z.array(z.string().min(1)),
  batches: z.array(
    z.strictObject({
      id: z.string().min(1),
      kind: z.literal("ddl"),
      sql: z.string().min(1),
      risk: z.enum(RISK_CLASSES),
      requires: z.array(z.string().min(1)).optional(),
    }),
  ),
  problems: z.array(
    z.strictObject({ code: z.string().min(1), batch: z.string().min(1).optional() }),
  ),
  approved: z
    .strictObject({ by: z.string().min(1), at: z.string().min(1), hash: z.string().min(1) })
    .optional(),
  generatedBy: z.string().min(1),
  generatedAt: z.string().min(1),
});

/** One rejection: where it is and which zod rule it broke. Codes only, never prose. */
export interface ReleaseArtifactIssue {
  /** Dotted path to the offending value; "" is the artifact root. */
  readonly path: string;
  /** Zod issue code, e.g. `invalid_type`, `too_small` or `unrecognized_keys`. */
  readonly code: string;
}

export type ReleaseArtifactParseResult =
  | { readonly ok: true; readonly artifact: ReleaseArtifact }
  | { readonly ok: false; readonly issues: readonly ReleaseArtifactIssue[] };

/** Validate an artifact value without throwing; callers branch on `ok`. */
export function parseReleaseArtifact(input: unknown): ReleaseArtifactParseResult {
  const result = releaseArtifactSchema.safeParse(input);
  if (result.success) return { ok: true, artifact: result.data };
  return {
    ok: false,
    issues: result.error.issues.map((issue) => ({
      path: issue.path.map((segment) => String(segment)).join("."),
      code: issue.code,
    })),
  };
}

/** The artifact before it is sealed: the same contract without the hash it computes. */
export type ReleaseArtifactInput = Omit<ReleaseArtifact, "planHash">;

/**
 * Compute `planHash` and return the sealed artifact.
 *
 * The hash covers the semantic body only (see `semanticBody`), so the approval can be
 * recorded later, and provenance (`generatedBy`/`generatedAt`) never changes what was
 * approved. An invalid input is a programming error in the generator, so it throws with the
 * machine issue list instead of returning a half-valid artifact.
 */
export async function sealReleaseArtifact(input: ReleaseArtifactInput): Promise<ReleaseArtifact> {
  const planHash = await hashSemanticBody(semanticBody(input));
  const result = parseReleaseArtifact({ ...input, planHash });
  if (!result.ok) {
    const codes = result.issues.map((issue) => `${issue.path}:${issue.code}`).join(",");
    throw new Error(`release_artifact_invalid:${codes}`);
  }
  return result.artifact;
}

/**
 * True only when `input` parses as an artifact and its approval names the artifact's own
 * plan hash. A missing approval, a malformed artifact and an approval for another plan are
 * all false — the deploy refuses, it never warns.
 */
export function approvalMatches(input: unknown): boolean {
  const result = parseReleaseArtifact(input);
  if (!result.ok) return false;
  const approval = result.artifact.approved;
  return approval !== undefined && approval.hash === result.artifact.planHash;
}

/**
 * The hashed view of the artifact: everything except `planHash` (the output), `approved`
 * (bound to it afterwards) and `generatedBy`/`generatedAt` (provenance, not semantics).
 * Array order stays as-is: batch order is execution order, and a reordered `destructive`
 * list is a different approval target.
 */
type SemanticBody = Pick<
  ReleaseArtifact,
  | "formatVersion"
  | "tag"
  | "from"
  | "to"
  | "digestVersion"
  | "fromDigest"
  | "toDigest"
  | "risk"
  | "destructive"
  | "batches"
  | "problems"
>;

function semanticBody(artifact: ReleaseArtifactInput): SemanticBody {
  return {
    formatVersion: artifact.formatVersion,
    tag: artifact.tag,
    from: artifact.from,
    to: artifact.to,
    digestVersion: artifact.digestVersion,
    fromDigest: artifact.fromDigest,
    toDigest: artifact.toDigest,
    risk: artifact.risk,
    destructive: artifact.destructive,
    batches: artifact.batches,
    problems: artifact.problems,
  };
}

async function hashSemanticBody(body: SemanticBody): Promise<string> {
  return `sha256:${await sha256Hex(canonicalJson(body))}`;
}

/**
 * Canonical JSON: object keys sorted by code unit recursively, no whitespace. Equivalent
 * bodies hash identically whatever key order the caller used, while one changed SQL byte,
 * risk class or destructive list changes the hash.
 */
function canonicalJson(value: unknown): string {
  return JSON.stringify(sortKeys(value));
}

function sortKeys(value: unknown): unknown {
  if (Array.isArray(value)) return value.map(sortKeys);
  if (value !== null && typeof value === "object") {
    const record = value as Record<string, unknown>;
    return Object.fromEntries(
      Object.keys(record)
        .toSorted(compareText)
        .map((key) => [key, sortKeys(record[key])]),
    );
  }
  return value;
}

/** Code-unit comparison, not `localeCompare`: the hash must not depend on the ICU locale. */
function compareText(left: string, right: string): number {
  if (left === right) return 0;
  return left < right ? -1 : 1;
}

interface WebCryptoLike {
  readonly subtle: {
    digest(algorithm: string, data: Uint8Array): Promise<ArrayBuffer>;
  };
}

const textEncoder = new TextEncoder();

/**
 * SHA-256 via WebCrypto: this module ships in the browser-safe core program, so
 * `node:crypto` is not available (same constraint as ./revision.ts).
 */
async function sha256Hex(value: string): Promise<string> {
  const webCrypto = (globalThis as unknown as { crypto?: WebCryptoLike }).crypto;
  if (webCrypto === undefined) {
    throw new Error("release artifact hashing requires globalThis.crypto.subtle (WebCrypto)");
  }
  const digest = await webCrypto.subtle.digest("SHA-256", textEncoder.encode(value));
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, "0")).join("");
}
